'use strict';
const Y=CycleCore;
state.cycleData=null;state.cycleColumns=null;state.cycleSettings={mode:'cycle',minSamples:5,hoursPerDay:24,unit:'hour'};
const cycleLabels=I18n.labels(()=> ({cycle:(I18n.t("cycle.736b0f03b6")),processing:'Start → End'}));
const cycleStatus=I18n.labels(()=> ({insufficient:(I18n.t("cycle.27b0634972")),reference:(I18n.t("cycle.75383a7088")),available:(I18n.t("cycle.7872ae38f0"))}));
function cycleSample(){
  let seed=714,t=Date.UTC(2026,7,1,8);const rows=[];
  const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
  const products=[...Array(40).fill('PROD-A'),...Array(24).fill('PROD-B'),...Array(8).fill('PROD-C'),...Array(3).fill('PROD-D')];
  for(let i=products.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[products[i],products[j]]=[products[j],products[i]];}
  const stamp=ms=>new Date(ms).toISOString().slice(0,19).replace('T',' ');
  for(const [i,product] of products.entries()){
    const duration=({ 'PROD-A':180,'PROD-B':300,'PROD-C':420,'PROD-D':150 }[product])+Math.round(random()*75);
    const gap=Math.round(20+random()*110)+(i%13===0?600:0);
    rows.push([product,`DEMO-${String(i+1).padStart(3,'0')}`,stamp(t),stamp(t+duration*60000)]);t+=(duration+gap)*60000;
  }
  return {headers:[(I18n.t("cycle.34fe253611")),(I18n.t("cycle.02a2e4578d")),'Start time','End time'],rows,name:(I18n.t("cycle.69258f2f34")),isDemo:true};
}
function cycleControls(){
  const d=state.cycleData,m=state.cycleColumns;
  return ("<div class=\"cycle-mapping\">" + ([['product',(I18n.t("cycle.34fe253611"))],['lot',(I18n.t("cycle.02a2e4578d"))],['start','Start time'],['end','End time']].map(([key,label])=>("<div>" + "<label for=\"cycle-" + (key) + "\">" + (label) + "</label>" + "<select id=\"cycle-" + (key) + "\" data-cycle-column=\"" + (key) + "\">" + "<option value=\"-1\">" + I18n.t("cycle.0d45f3e7ec") + "</option>" + (options(d.headers,m[key])) + "</select>" + "</div>")).join('')) + "</div>" + "<div class=\"data-caption\" style=\"margin-top:12px\">" + I18n.t("cycle.d4bc08dc3e") + "</div>" + "<div class=\"divider\">" + "</div>" + "<div class=\"cycle-settings\">" + "<div>" + "<label for=\"cycle-mode\">" + I18n.t("cycle.7794b26b41") + "</label>" + "<select id=\"cycle-mode\">" + "<option value=\"cycle\" " + (state.cycleSettings.mode==='cycle'?'selected':'') + ">" + I18n.t("cycle.7171362561") + "</option>" + "<option value=\"processing\" " + (state.cycleSettings.mode==='processing'?'selected':'') + ">" + I18n.t("cycle.486c370b32") + "</option>" + "</select>" + "</div>" + "<div>" + "<label for=\"cycle-equipment\">" + I18n.t("cycle.4cc3cee579") + "</label>" + "<select id=\"cycle-equipment\" data-cycle-column=\"equipment\">" + "<option value=\"-1\">" + I18n.t("cycle.bf6cf8d2ef") + "</option>" + (options(d.headers,m.equipment)) + "</select>" + "</div>" + "<div>" + "<label for=\"cycle-min\">" + I18n.t("cycle.53f3b31451") + "</label>" + "<input id=\"cycle-min\" type=\"number\" min=\"2\" max=\"1000\" step=\"1\" value=\"" + (esc(state.cycleSettings.minSamples)) + "\">" + "</div>" + "<div>" + "<label for=\"cycle-hours\">" + I18n.t("cycle.203fac6361") + "</label>" + "<div class=\"input-suffix\">" + "<input id=\"cycle-hours\" type=\"number\" min=\"0.1\" max=\"24\" step=\"0.5\" value=\"" + (esc(state.cycleSettings.hoursPerDay)) + "\">" + "<span>" + I18n.t("cycle.09558b2cc6") + "</span>" + "</div>" + "</div>" + "<div>" + "<label for=\"cycle-unit\">" + I18n.t("cycle.d5f3202ac7") + "</label>" + "<select id=\"cycle-unit\">" + "<option value=\"hour\" " + (state.cycleSettings.unit==='hour'?'selected':'') + ">" + I18n.t("cycle.09558b2cc6") + "</option>" + "<option value=\"minute\" " + (state.cycleSettings.unit==='minute'?'selected':'') + ">" + I18n.t("cycle.0d7416e2e2") + "</option>" + "</select>" + "</div>" + "</div>");
}
function cycleEquipment(record){return state.cycleColumns?.equipment<0?I18n.t('cycle.single'):!record.equipment||record.equipment==='未指定'&&!state.cycleResult?.records.some(r=>r.equipment==='未指定')?I18n.t('cycle.unspecified'):record.equipment;}
function cycleTime(ms,kind){return ms===null?'':new Date(ms).toISOString().slice(0,19).replace('T',' ')+(kind==='instant'?' UTC':'');}
function cycleNotes(r){return [...r.errors,r.overlap?(r.processing!==null?(I18n.t("cycle.ba6cdb09b1")):(I18n.t("cycle.0ad96c3465"))):'',r.cycleReason].filter(Boolean).join(' / ');}
function cycleChart(groups,metric,factor,unit){
  const all=groups.filter(g=>g[metric].p50!==null),shown=all.slice(0,15);
  if(!shown.length)return ("<div class=\"empty\">" + I18n.t("cycle.7dfeb6f722") + "</div>");
  const w=860,h=shown.length*52+46,left=180,right=80,max=Math.max(...shown.map(g=>g[metric].p50/factor),1),width=w-left-right;
  let svg='';for(let i=0;i<=4;i++){const value=max*i/4,x=left+width*i/4;svg+=`<line class="grid" x1="${x}" x2="${x}" y1="8" y2="${h-32}"/><text x="${x}" y="${h-12}" text-anchor="middle">${fmt(value,1)}</text>`;}
  shown.forEach((g,i)=>{const y=i*52+12,label=(state.cycleColumns.equipment>=0?cycleEquipment(g)+' / ':'')+g.product;svg+=`<text x="${left-12}" y="${y+17}" text-anchor="end"><title>${esc(label)}</title>${esc(label.length>17?label.slice(0,16)+'…':label)}</text>`;for(const [k,color,dy] of [['p25','#147e70',0],['p50','#79b8aa',16]]){const v=g[metric][k]/factor;svg+=`<rect x="${left}" y="${y+dy}" width="${v/max*width}" height="11" fill="${color}" rx="2"><title>${esc(label)} / ${k.toUpperCase()}: ${fmt(v,2)} ${unit}</title></rect><text x="${left+v/max*width+6}" y="${y+dy+10}">${fmt(v,1)}</text>`;}});
  return `<div class="cycle-chart-wrap">${chartBase(w,h,svg,(I18n.t("cycle.5cf0f232cd", [cycleLabels[metric], unit])))}</div>${all.length>15?("<p class=\"muted\">" + I18n.t("cycle.ad8f50a8d3") + "</p>"):''}`;
}
function renderCycle(){
  if(!state.cycleData){state.cycleData=cycleSample();state.cycleColumns=Y.suggestColumns(state.cycleData.headers);}
  const d=state.cycleData,s=state.cycleSettings,metric=s.mode,factor=s.unit==='hour'?60:1,unit=s.unit==='hour'?(I18n.t("cycle.09558b2cc6")):(I18n.t("cycle.0d7416e2e2"));
  let r,error;
  try{if(!Number.isFinite(s.hoursPerDay)||s.hoursPerDay<=0||s.hoursPerDay>24)throw Error((I18n.t("cycle.4aa7e03733")));r=Y.analyze(d.rows,state.cycleColumns,{minSamples:s.minSamples,date1904:d.date1904});}catch(e){error=e.message;}
  state.cycleResult=r||null;
  let html=loadPanel();
  if(error)html+=`<div class="notice error" role="alert">${esc(error)}</div>`;
  else{
    const eligible=r.groups.filter(g=>g[metric].p50!==null),shown=r.groups.slice(0,300);
    const duration=v=>fmt(v===null?null:v/factor,2),rate=v=>v>0?fmt(s.hoursPerDay*60/v,2):'—';
    html+=("<div class=\"toolbar\">" + "<h2>" + "<span class=\"step\">" + "02" + "</span>" + I18n.t("cycle.48974417de") + "</h2>" + "<div class=\"load-actions no-print\">" + "<button id=\"cycle-export\" " + (r.records.length?'':'disabled') + ">" + I18n.t("cycle.30dd88e780") + "</button>" + "<button id=\"cycle-print\">" + I18n.t("cycle.283f162b9e") + "</button>" + "</div>" + "</div>" + "<div class=\"print-title\">" + I18n.t("cycle.def90c53b7", [esc(d.name), cycleLabels[metric], s.minSamples, s.hoursPerDay, d.isDemo?(I18n.t("cycle.2b0104b2b5")):(I18n.t("cycle.243e7f8802"))]) + "</div>" + "<div class=\"stats\">" + "<div class=\"stat featured\">" + "<div class=\"stat-label\">" + I18n.t("cycle.ab6144b9f8", [metric==='cycle'?(I18n.t("cycle.420745a078")):(I18n.t("cycle.153b8bb047"))]) + "</div>" + "<div class=\"stat-value\">" + (metric==='cycle'?r.cycleCount:r.processingCount) + "<small>" + " " + I18n.t("cycle.04d7e6fc2c") + "</small>" + "</div>" + "<div class=\"stat-sub\">" + (cycleLabels[metric]) + "</div>" + "</div>" + "<div class=\"stat\">" + "<div class=\"stat-label\">" + I18n.t("cycle.aadd336ea0") + "</div>" + "<div class=\"stat-value\">" + (eligible.length) + "<small>" + " / " + (r.groups.length) + "</small>" + "</div>" + "<div class=\"stat-sub\">" + I18n.t("cycle.1e782e114c", [s.minSamples]) + "</div>" + "</div>" + "<div class=\"stat\">" + "<div class=\"stat-label\">" + I18n.t("cycle.4f28d25655") + "</div>" + "<div class=\"stat-value\">" + (r.records.length) + "<small>" + " " + I18n.t("cycle.04d7e6fc2c") + "</small>" + "</div>" + "<div class=\"stat-sub\">" + I18n.t("cycle.cb7cc17923", [r.blankRows]) + "</div>" + "</div>" + "<div class=\"stat\">" + "<div class=\"stat-label\">" + I18n.t("cycle.1f8aef8c6b") + "</div>" + "<div class=\"stat-value " + (r.invalidRows?'bad':'') + "\">" + (r.invalidRows) + "<small>" + " " + I18n.t("cycle.04d7e6fc2c") + "</small>" + "</div>" + "<div class=\"stat-sub\">" + I18n.t("cycle.cfc2eb3d30") + "</div>" + "</div>" + "</div>");
    html+=("<div class=\"notice neutral\">" + "<span>" + I18n.t("cycle.4a28c13bd7", [metric==='cycle'?(I18n.t("cycle.849d1e522e")):(I18n.t("cycle.ef8c10c5ed"))]) + "</span>" + "</div>");
    if(r.invalidRows||r.overlapRows)html+=("<div class=\"notice\">" + "<span>" + I18n.t("cycle.1021741825", [r.invalidRows, r.overlapRows, r.blockedLines?(I18n.t("cycle.b2cb28bf20", [r.blockedLines])):'']) + "</span>" + "</div>");
    html+=("<section class=\"panel\">" + "<div class=\"chart-title\">" + "<h3>" + I18n.t("cycle.ec26df6328", [cycleLabels[metric], formulaTip((I18n.t("cycle.0e6114a2b8")),(I18n.t("cycle.249ec4f00f")))]) + "</h3>" + "<small>" + I18n.t("cycle.5303a3f699", [unit]) + "</small>" + "</div>" + "<div class=\"legend cycle-legend\">" + "<span>" + "<i>" + "</i>" + I18n.t("cycle.bf1f90bcee") + "</span>" + "<span>" + "<i style=\"background:#79b8aa\">" + "</i>" + I18n.t("cycle.3f855359ac") + "</span>" + "</div>" + (cycleChart(r.groups,metric,factor,unit)) + "</section>");
    html+=("<section class=\"panel\">" + "<div class=\"panel-head\">" + "<h3>" + I18n.t("cycle.28c9726f9a") + "</h3>" + "<span class=\"muted\">" + (cycleLabels[metric]) + " / " + (unit) + "</span>" + "</div>" + "<div class=\"table-wrap\">" + "<table>" + "<thead>" + "<tr>" + "<th>" + I18n.t("cycle.ae4ededb0a") + "</th>" + "<th>" + I18n.t("cycle.a6a61230ff") + "</th>" + "<th class=\"num\">" + I18n.t("cycle.fe07659c1c") + "</th>" + "<th class=\"num\">" + "P25" + "</th>" + "<th class=\"num\">" + "P50" + "</th>" + "<th class=\"num\">" + I18n.t("cycle.606ecf4d72") + "<br>" + I18n.t("cycle.64fb2b954e") + "</th>" + "<th class=\"num\">" + I18n.t("cycle.4947708161") + "<br>" + I18n.t("cycle.64fb2b954e") + "</th>" + "<th>" + I18n.t("cycle.a4681e8882") + "</th>" + "</tr>" + "</thead>" + "<tbody>" + (shown.map(g=>{const q=g[metric];return `<tr><td>${esc(g.product)}</td><td>${esc(cycleEquipment(g))}</td><td class="num">${q.n}</td><td class="num">${duration(q.p25)}</td><td class="num">${duration(q.p50)}</td><td class="num">${rate(q.p50)}</td><td class="num">${rate(q.p25)}</td><td><span class="tag ${q.status==='available'?'':'demo'}">${cycleStatus[q.status]}</span></td></tr>`;}).join('')) + "</tbody>" + "</table>" + "</div>" + (r.groups.length>300?("<p class=\"muted\">" + I18n.t("cycle.2640826641") + "</p>"):'') + "<p class=\"section-note\">" + I18n.t("cycle.83863d2438", [s.minSamples]) + "</p>" + "<p class=\"section-note\">" + I18n.t("cycle.e5fa8c7a27", [s.hoursPerDay]) + "</p>" + "</section>");
    html+=("<section class=\"panel\">" + "<details>" + "<summary>" + I18n.t("cycle.9ca804db42") + "</summary>" + "<div class=\"table-wrap\">" + "<table>" + "<thead>" + "<tr>" + "<th>" + I18n.t("cycle.644b123cc2") + "</th>" + "<th class=\"num\">" + I18n.t("cycle.075d8f1f26") + "</th>" + "<th class=\"num\">" + I18n.t("cycle.d5119d52e7") + "</th>" + "<th class=\"num\">" + I18n.t("cycle.f5e862f192") + "</th>" + "<th class=\"num\">" + I18n.t("cycle.2736979f28") + "</th>" + "<th class=\"num\">" + I18n.t("cycle.4a881088e1") + "</th>" + "<th class=\"num\">" + I18n.t("cycle.ba994124e3") + "</th>" + "</tr>" + "</thead>" + "<tbody>" + (shown.map(g=>`<tr><td>${esc(g.product)} / ${esc(cycleEquipment(g))}</td><td class="num">${g.processing.n}</td><td class="num">${duration(g.processing.p25)}</td><td class="num">${duration(g.processing.p50)}</td><td class="num">${g.gap.n}</td><td class="num">${duration(g.gap.p25)}</td><td class="num">${duration(g.gap.p50)}</td></tr>`).join('')) + "</tbody>" + "</table>" + "</div>" + "<p>" + I18n.t("cycle.c95e7a66e5", [unit]) + "</p>" + "</details>" + "</section>");
    html+=("<section class=\"panel\">" + "<details>" + "<summary>" + I18n.t("cycle.e79da46ddb") + "</summary>" + "<p>" + I18n.t("cycle.d6ce7e9b22", [unit]) + "</p>" + "<div class=\"table-wrap\">" + "<table>" + "<thead>" + "<tr>" + ([(I18n.t("cycle.fb5883fbaa")),(I18n.t("cycle.ae4ededb0a")),(I18n.t("cycle.d1372ab167")),(I18n.t("cycle.a6a61230ff")),'Start','End',(I18n.t("cycle.0d848b315b")),(I18n.t("cycle.6961bfe1ab")),(I18n.t("cycle.c75ba6e453")),(I18n.t("cycle.185057c38d")),(I18n.t("cycle.420745a078")),(I18n.t("cycle.0bdf8e53ff"))].map(h=>`<th>${h}</th>`).join('')) + "</tr>" + "</thead>" + "<tbody>" + (r.records.slice(0,100).map(x=>`<tr><td>${x.index+1}</td><td>${esc(x.product)}</td><td>${esc(x.lot)}</td><td>${esc(cycleEquipment(x))}</td><td>${esc(cycleTime(x.start,x.kind))}</td><td>${esc(cycleTime(x.end,x.kind))}</td><td>${esc(cycleTime(x.nextStart,x.kind))}</td><td>${esc(x.nextProduct)}</td><td>${duration(x.processing)}</td><td>${duration(x.gap)}</td><td>${duration(x.cycle)}</td><td>${esc(cycleNotes(x))}</td></tr>`).join('')) + "</tbody>" + "</table>" + "</div>" + "</details>" + "<details>" + "<summary>" + I18n.t("cycle.a8b5bbc7b5") + "</summary>" + "<p>" + I18n.t("cycle.a67e42d48e") + "</p>" + "<p>" + I18n.t("cycle.4a8a5b8b47") + "</p>" + "<p>" + I18n.t("cycle.541515d3ed") + "<a href=\"https://www.itl.nist.gov/div898/handbook/prc/section2/prc262.htm\" target=\"_blank\" rel=\"noreferrer\">" + I18n.t("cycle.92f7c17547") + "</a>" + "</p>" + "</details>" + "</section>");
  }
  $('#workspace').innerHTML=html;bindLoad();
  $$('[data-cycle-column]').forEach(el=>el.onchange=e=>{state.cycleColumns[el.dataset.cycleColumn]=Number(e.target.value);state.appliedPreset='';state.restoreNote='';renderCycle();});
  for(const [id,key,isNumber] of [['cycle-mode','mode',false],['cycle-min','minSamples',true],['cycle-hours','hoursPerDay',true],['cycle-unit','unit',false]])$('#'+id).onchange=e=>{state.cycleSettings[key]=isNumber?Number(e.target.value):e.target.value;state.appliedPreset='';state.restoreNote='';renderCycle();};
  if($('#cycle-export'))$('#cycle-export').onclick=()=>safe(()=>exportReportExcel('cycle'));
  if($('#cycle-print')){$('#cycle-print').textContent=(I18n.t("cycle.cb0a373cac"));$('#cycle-print').onclick=()=>safe(()=>openReport('cycle'));}
}
